    counts[rank] = (counts[rank] || 0) + 1;
  }
  // Groups of cards sharing a rank, e.g. [{ rank, count }, ...].
  const groups = Object.entries(counts).map(([rank, count]) => ({
    rank: Number(rank),
    count,
  }));

  const isFlush = suits.every((suit) => suit === suits[0]);

  // Straight detection, including the ace-low "wheel" (A 2 3 4 5).
  const uniqueRanks = [...new Set(ranks)].sort((a, b) => a - b);
  let straightHigh = null;
  if (uniqueRanks.length === 5) {
    if (uniqueRanks[4] - uniqueRanks[0] === 4) {
      straightHigh = uniqueRanks[4];
    } else if (uniqueRanks.join(',') === '2,3,4,5,14') {
      straightHigh = 5;
    }
  }
  const isStraight = straightHigh !== null;

  const countSignature = groups
    .map((group) => group.count)
    .sort((a, b) => b - a);

  let category;
  if (isStraight && isFlush) category = 9; // straight flush
  else if (countSignature[0] === 4) category = 8; // four of a kind
  else if (countSignature[0] === 3 && countSignature[1] === 2) category = 7; // full house
  else if (isFlush) category = 6; // flush
  else if (isStraight) category = 5; // straight
  else if (countSignature[0] === 3) category = 4; // three of a kind
  else if (countSignature[0] === 2 && countSignature[1] === 2) category = 3; // two pair
  else if (countSignature[0] === 2) category = 2; // one pair
  else category = 1; // high card

  // Tiebreakers, ordered most-significant first.
  let tiebreakers;
  switch (category) {
    case 9: // straight flush: just the highest card
    case 5: // straight: just the highest card
      tiebreakers = [straightHigh];
      break;
    case 8: // four of a kind: quad rank, then kicker
    case 7: // full house: triplet rank, then pair rank
    case 4: // three of a kind: triplet rank, then kickers
    case 2: // one pair: pair rank, then kickers
      tiebreakers = groups
        .sort((a, b) => b.count - a.count || b.rank - a.rank)
        .map((group) => group.rank);
      break;
    case 3: // two pair: high pair, low pair, then kicker
      tiebreakers = groups
        .sort((a, b) => b.rank - a.rank)
        .map((group) => group.rank);
      break;
    default: // flush / high card: all five cards, highest first
      tiebreakers = [...ranks].sort((a, b) => b - a);
  }

  return [category, ...tiebreakers];
