const compareScores = (a, b) => {
  const length = Math.min(a.length, b.length);
  for (let i = 0; i < length; i += 1) {
    if (a[i] !== b[i]) {
      return a[i] > b[i] ? 1 : -1;
    }
  }
  return 0;
};

export const bestHands = (hands) => {
  const scores = hands.map(scoreHand);
  let best = scores[0];
  const winners = [];

  for (let i = 0; i < hands.length; i += 1) {
    const comparison = compareScores(scores[i], best);
    if (comparison > 0) {
      best = scores[i];
      winners.length = 0;
    }
    if (comparison >= 0) {
      winners.push(hands[i]);
    }
  }

  return winners;
};
